#!/usr/bin/env python3
"""Commit A: replace 5 JSON.parse(record.content || '{}') sites in bin/cck.js
with backwards-compatible `record.content ?? {}`. Asserts each pattern is unique."""

path = '/Users/arpit/Desktop/super-claude-kit/bin/cck.js'
with open(path) as f:
    src = f.read()

pairs = [
    # Site 1: mapStatus (line ~1768)
    ("""  let data = {};
  try { data = JSON.parse(meta.content || '{}'); } catch {}

  console.log('Codebase Map Status');""",
     """  const data = meta.content ?? {};

  console.log('Codebase Map Status');"""),

    # Site 2: mapShow (line ~1815)
    ("""  let data = {};
  try { data = JSON.parse(record.content || '{}'); } catch {}

  if (record.type === 'COLLECTION') {""",
     """  const data = record.content ?? {};

  if (record.type === 'COLLECTION') {"""),

    # Site 3: mapUpdate (line ~1860)
    ("""  let data = {};
  try { data = JSON.parse(meta.content || '{}'); } catch {}
  const storedSha = data.last_scan_sha;""",
     """  const data = meta.content ?? {};
  const storedSha = data.last_scan_sha;"""),

    # Site 4: mapHot (line ~1928, 4-space indent inside loop)
    ("""    let data = {};
    try { data = JSON.parse(record.content || '{}'); } catch {}
    if (Array.isArray(data.imported_by) && data.imported_by.length > 0) {""",
     """    const data = record.content ?? {};
    if (Array.isArray(data.imported_by) && data.imported_by.length > 0) {"""),

    # Site 5: mapStubs (line ~1975, 4-space indent inside loop)
    ("""    let data = {};
    try { data = JSON.parse(record.content || '{}'); } catch {}
    if (data.understanding_depth === 'stub') {""",
     """    const data = record.content ?? {};
    if (data.understanding_depth === 'stub') {"""),
]

for i, (old, new) in enumerate(pairs, 1):
    count = src.count(old)
    assert count == 1, f"Site {i}: expected exactly 1 match, got {count}"
    src = src.replace(old, new, 1)
    print(f"Site {i}: applied")

with open(path, 'w') as f:
    f.write(src)

print("Commit A: 5 sites rewritten")

